INSERT INTO `RawIngestEvent` (`id`, `workspaceId`, `eventId`, `idempotencyKey`, `sourceType`, `eventType`, `occurredAt`, `sourcePath`, `contentHash`, `payload`, `createdAt`) VALUES ('cmo6sfg1b004ybq98hg5u7o9r', 'cmo6scwtp0000u1984s0is07h', 'role:build-specialist:v1:50336a38b91e', 'ee1d14b695ac27a339f9f65aca6003531642f9658f88b4b5cdc1c50f465933b1', 'registry-json', 'registry.role.snapshot', '2026-04-20 06:02:13.102', '.agents/registry/roles.json', '50336a38b91e12acc06ec5bbceb9f65a4181de08619826f4c0e4692d7b330242', '{\"item\": {\"name\": \"构建专家\", \"source\": \".agents/roles/domains/engineering/build-specialist.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"rule_ids\": [\"coding-standard\", \"format-check-standard\", \"audit-report-standard\"], \"skill_priority\": [\"config-and-secret-scan\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"config-and-secret-scan\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先判断问题位于构建入口、构建性能还是产物异常，再给出建议。\", \"优先复用现有构建脚本和配置，不新增无必要工具链。\"], \"blocked_when\": [\"若构建变更会影响发布链但未给出验证与回滚路径，不得直接放行。\"]}}}, \"slug\": \"build-specialist\", \"version\": 1, \"category\": \"role\", \"entityId\": \"build-specialist\", \"registry\": \"agents\", \"entityType\": \"role\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.103');
INSERT INTO `RawIngestEvent` (`id`, `workspaceId`, `eventId`, `idempotencyKey`, `sourceType`, `eventType`, `occurredAt`, `sourcePath`, `contentHash`, `payload`, `createdAt`) VALUES ('cmo6sfg1o0054bq98trwjdw3t', 'cmo6scwtp0000u1984s0is07h', 'role:dependency-governor:v1:2eb96f539f1c', 'ab07c74d5aba8f1e4bee4647e728caa619ed82e5f81692c15617064c6d5b6757', 'registry-json', 'registry.role.snapshot', '2026-04-20 06:02:13.115', '.agents/registry/roles.json', '2eb96f539f1c57581b16af2534e4d10631868b68a77968fff3bfcefcb3e3e2f1', '{\"item\": {\"name\": \"依赖治理专家\", \"source\": \".agents/roles/domains/engineering/dependency-governor.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"rule_ids\": [\"coding-standard\", \"format-check-standard\", \"audit-report-standard\"], \"skill_priority\": [\"dependency-impact-graph\", \"config-and-secret-scan\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"dependency-impact-graph\", \"config-and-secret-scan\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先区分新增、升级、移除三类依赖变更，再给最小影响建议。\", \"涉及安装来源、registry 或脚本依赖时，需要补验证与回滚说明。\"], \"blocked_when\": [\"若依赖变更影响面未分析清楚，不得直接建议进入实现或发布。\"]}}}, \"slug\": \"dependency-governor\", \"version\": 1, \"category\": \"role\", \"entityId\": \"dependency-governor\", \"registry\": \"agents\", \"entityType\": \"role\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.116');
INSERT INTO `RawIngestEvent` (`id`, `workspaceId`, `eventId`, `idempotencyKey`, `sourceType`, `eventType`, `occurredAt`, `sourcePath`, `contentHash`, `payload`, `createdAt`) VALUES ('cmo6sfg21005bbq987tlbc0hv', 'cmo6scwtp0000u1984s0is07h', 'role:architecture-advisor:v1:4a6042ca5e23', '0a99a504f5163e76bd594c0a464204fedc49a231df3f607a3d754b63daf02d67', 'registry-json', 'registry.role.snapshot', '2026-04-20 06:02:13.129', '.agents/registry/roles.json', '4a6042ca5e23b60e534a40b70909a87df7987b99b09dd670709db0521f8de803', '{\"item\": {\"name\": \"架构顾问专家\", \"source\": \".agents/roles/domains/engineering/architecture-advisor.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"rule_ids\": [\"project-overview\", \"project-structure\", \"api-standard\", \"route-standard\", \"style-standard\"], \"skill_priority\": [\"create-proposal\", \"dependency-impact-graph\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"create-proposal\", \"dependency-impact-graph\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先收口模块边界和职责拆分，再讨论实现细节。\", \"若结构性改动会影响多个模块，需要显式列出影响面和拆分建议。\"], \"blocked_when\": [\"若关键边界仍不清楚，不得把结构性问题直接下放到实现阶段临时决定。\"]}}}, \"slug\": \"architecture-advisor\", \"version\": 1, \"category\": \"role\", \"entityId\": \"architecture-advisor\", \"registry\": \"agents\", \"entityType\": \"role\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.129');
INSERT INTO `RawIngestEvent` (`id`, `workspaceId`, `eventId`, `idempotencyKey`, `sourceType`, `eventType`, `occurredAt`, `sourcePath`, `contentHash`, `payload`, `createdAt`) VALUES ('cmo6sfg2i005kbq98tiudk95t', 'cmo6scwtp0000u1984s0is07h', 'role:unit-test-specialist:v1:186c61df33e1', 'd79740c1a72e05a5c75479ee252b748fe23f361bdc2a5a200319a410a319321e', 'registry-json', 'registry.role.snapshot', '2026-04-20 06:02:13.145', '.agents/registry/roles.json', '186c61df33e1f9f96090e0b191b344b5a993acf0eb117501332001e56bc27dff', '{\"item\": {\"name\": \"单元测试专家\", \"source\": \".agents/roles/domains/testing/unit-test-specialist.md\", \"status\": \"active\", \"domains\": [\"testing\"], \"rule_ids\": [\"coding-standard\", \"test-standard\", \"audit-report-standard\"], \"skill_priority\": [\"create-test\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"create-test\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先判断当前改动是否真的需要补测，再给出最小但有效的测试策略。\", \"quick-fix 下优先读取 bugfix 与实现说明，不把轻量修复默认升级成完整测试改造。\"], \"blocked_when\": [\"若关键回归路径已经受损但仍拒绝补测或给出测试建议，不得给出“风险可忽略”的判断。\"]}}}, \"slug\": \"unit-test-specialist\", \"version\": 1, \"category\": \"role\", \"entityId\": \"unit-test-specialist\", \"registry\": \"agents\", \"entityType\": \"role\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.146');
