INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sffxh0034bq9881mw6k1p', 'cmo6scwtp0000u1984s0is07h', 'role', 'task-orchestrator', '任务主代理', NULL, 'active', 1, '.agents/roles/common/task-orchestrator.md', '{\"name\": \"任务主代理\", \"source\": \".agents/roles/common/task-orchestrator.md\", \"status\": \"active\", \"domains\": [\"orchestration\"], \"profiles\": [\"vue\", \"react\"], \"registry\": \"agents\", \"rule_ids\": [\"project-overview\", \"project-structure\", \"api-standard\", \"route-standard\", \"style-standard\"], \"rawEventId\": \"cmo6sffxe0033bq98jl4rlbdi\", \"registryPath\": \".agents/registry/roles.json\", \"rule_contract_profiles\": {\"vue\": {\"must_follow\": [\"Vue 页面类任务优先以 src/views、src/router/modules、src/api、src/api/types、src/style.css 等当前仓库落点编排。\", \"若仓库缺少 vue-router 或请求层骨架，要先把“补骨架还是保持占位入口”写进编排约束。\", \"mock-first、真实接口、Pinia/store 与主题变量策略需要在首轮编排时明确，不留到实现阶段临时猜。\"]}, \"default\": {\"must_follow\": [\"首轮编排必须优先吸收仓库现状与规则，再决定 flow、delivery_profile 和人工确认点。\", \"能从仓库结构、项目规则推断的路由/API/mock/样式事实，优先转成 assumptions 或 routing constraints。\"], \"blocked_when\": [\"高风险领域的流程、安全、合规、风控或权限边界仍未确认时，不得放行到 frontend-implementer。\"]}}}', '2026-04-20 06:02:12.966', '2026-04-20 06:02:12.966');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sffxz003dbq98tckmv8f3', 'cmo6scwtp0000u1984s0is07h', 'role', 'requirement-analyst', '需求解析专家', NULL, 'active', 1, '.agents/roles/common/requirement-analyst.md', '{\"name\": \"需求解析专家\", \"source\": \".agents/roles/common/requirement-analyst.md\", \"status\": \"active\", \"domains\": [\"demand-design\"], \"profiles\": [\"vue\", \"react\"], \"registry\": \"agents\", \"rule_ids\": [\"project-overview\", \"project-structure\", \"api-standard\", \"route-standard\", \"style-standard\"], \"rawEventId\": \"cmo6sffxv003cbq987lzflft5\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"create-proposal\", \"design-analysis\"], \"openspec_actions\": [\"propose\"], \"required_outputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"runtime_transition\": {\"action\": \"handoff\", \"status\": \"running\", \"message\": \"handoff to frontend-implementer after requirement convergence\", \"to_role\": \"frontend-implementer\", \"next_role\": \"code-guardian\"}, \"micro_skill_allowlist\": [\"create-proposal\", \"design-analysis\"], \"openspec_rule_sections\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"rule_contract_profiles\": {\"vue\": {\"must_follow\": [\"页面任务优先对齐 src/views/<page>/index.vue 与 src/router/modules/<module>.ts 的落点约定。\", \"若为 mock 或占位页，明确写清 src/mock 或本地 mock 方案，以及“不接真实 API”的边界。\", \"样式和视觉约束需对齐主题 CSS 变量，不要把硬编码颜色或自由样式当默认方案。\"]}, \"default\": {\"must_follow\": [\"先把项目定位、目录落点、路由/API/样式约定吸收到 proposal/specs/design/tasks，不要把规范已明确的信息重复写成 missing_inputs。\", \"需求收敛必须落到当前仓库可实施的页面、路由、接口或 mock 落点，而不是抽象方案。\"], \"blocked_when\": [\"高风险领域的流程、安全、合规、风控或权限边界仍未确认时，必须维持 before-implementation 门禁。\"]}}}', '2026-04-20 06:02:12.983', '2026-04-20 06:02:12.983');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sffyh003obq98ikv28cd3', 'cmo6scwtp0000u1984s0is07h', 'role', 'frontend-implementer', '前端实现专家', NULL, 'active', 1, '.agents/roles/common/frontend-implementer.md', '{\"name\": \"前端实现专家\", \"source\": \".agents/roles/common/frontend-implementer.md\", \"status\": \"active\", \"domains\": [\"engineering\", \"delivery\"], \"profiles\": [\"vue\", \"react\"], \"registry\": \"agents\", \"rule_ids\": [\"project-structure\", \"component-standard\", \"route-standard\", \"api-standard\", \"store-standard\", \"style-standard\"], \"rawEventId\": \"cmo6sffye003nbq98konnmtrd\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"create-view\", \"create-route\", \"create-api\", \"theme-variables\", \"create-component\", \"create-store\", \"execute-task\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"openspec_actions\": [\"apply\"], \"runtime_transition\": {\"action\": \"handoff\", \"status\": \"running\", \"message\": \"handoff to code-guardian after implementation delivery\", \"to_role\": \"code-guardian\", \"next_role\": null}, \"micro_skill_allowlist\": [\"create-view\", \"create-route\", \"create-api\", \"theme-variables\", \"create-component\", \"create-store\"], \"openspec_rule_sections\": [\"specs\", \"tasks\", \"design\"], \"rule_contract_profiles\": {\"vue\": {\"must_follow\": [\"Vue 视图优先落在 src/views/<page>/index.vue；页面专用组件落在 src/views/<page>/components/。\", \"路由统一放在 src/router/modules/，页面路由必须懒加载，并补齐 meta.title / requiresAuth 等项目约定。\", \"接口统一走 src/api/<module>.ts 与 src/api/types/<module>.ts，组件或页面里禁止直接调 request。\", \"状态管理统一走 Pinia 和 src/store/modules/；mock-first 场景优先本地状态，不预建复杂 store。\", \"样式必须使用主题变量和 scoped/CSS Modules，禁止硬编码颜色值。\"]}, \"default\": {\"must_follow\": [\"优先复用现有目录、路由、请求封装、状态管理和样式变量约定。\", \"实现前先对齐 proposal/specs/design/tasks 的范围与落点，不要自行扩 scope。\", \"若 verification 失败触发 auto-fix，只修失败步骤对应的问题，不新增功能、不顺手重构。\"], \"blocked_when\": [\"proposal/specs/design/tasks 未落盘或仍处于 before-implementation 审批门禁时，禁止改业务代码。\"]}}}', '2026-04-20 06:02:13.001', '2026-04-20 06:02:13.001');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sffz90045bq98ewwgusfe', 'cmo6scwtp0000u1984s0is07h', 'role', 'code-guardian', '规范守护者', NULL, 'active', 1, '.agents/roles/common/code-guardian.md', '{\"name\": \"规范守护者\", \"source\": \".agents/roles/common/code-guardian.md\", \"status\": \"active\", \"domains\": [\"governance\", \"testing\"], \"profiles\": [\"vue\", \"react\"], \"registry\": \"agents\", \"rule_ids\": [\"coding-standard\", \"api-standard\", \"route-standard\", \"style-standard\", \"test-standard\", \"format-check-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sffz70044bq98qpadbr1k\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"ui-verification\", \"web-design-guidelines\", \"create-test\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"openspec_actions\": [\"verify\"], \"required_outputs\": [\"checklist\", \"iterations\"], \"runtime_transition\": {\"action\": \"gate-blocked\", \"status\": \"waiting-approval\", \"message\": \"wait for archive confirmation after code-guardian final review\", \"to_role\": \"code-guardian\", \"next_role\": \"archive-change\", \"pending_gate\": \"before-archive\"}, \"micro_skill_allowlist\": [\"ui-verification\", \"web-design-guidelines\"], \"openspec_rule_sections\": [\"tasks\", \"specs\", \"design\", \"checklist\", \"iterations\"], \"rule_contract_profiles\": {\"vue\": {\"must_follow\": [\"核查页面是否落在 src/views、路由是否落在 src/router/modules，并保持动态导入。\", \"核查 API 是否通过 src/api 封装、类型是否放在 src/api/types，页面中未直接调 request。\", \"核查样式是否使用主题变量、scoped 或 CSS Modules，而不是硬编码全局样式。\", \"核查 Pinia/store、mock 与 proposal/specs/design/tasks 的边界是否一致，避免“演示页写成生产页”。\"]}, \"default\": {\"must_follow\": [\"以 proposal/specs/design/tasks 和项目规则为准检查实现，而不是只做泛化 lint。\", \"必须给出阻断项、非阻断项和交付建议，不能写成模糊建议列表。\", \"若实现阶段经历过 auto-fix 仍未通过 verification，必须按阻断项处理，不能以“后续再看”放行。\"], \"blocked_when\": [\"存在与项目规范冲突的目录、路由、API、样式或测试问题时，不得给 complete 结论。\"]}}}', '2026-04-20 06:02:13.029', '2026-04-20 06:02:13.029');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg01004jbq98m2slvxtv', 'cmo6scwtp0000u1984s0is07h', 'role', 'archive-change', '归档专家', NULL, 'active', 1, '.agents/roles/common/archive-change.md', '{\"name\": \"归档专家\", \"source\": \".agents/roles/common/archive-change.md\", \"status\": \"active\", \"domains\": [\"delivery\", \"documentation\"], \"registry\": \"agents\", \"rule_ids\": [\"audit-report-standard\"], \"rawEventId\": \"cmo6sffzy004ibq98ssauw025\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"archive-change\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\", \"checklist\", \"iterations\"], \"openspec_actions\": [\"archive\"], \"runtime_transition\": {\"action\": \"complete\", \"status\": \"success\", \"message\": \"run completed after archive-change closeout\", \"to_role\": \"archive-change\", \"next_role\": null}, \"micro_skill_allowlist\": [\"archive-change\"], \"openspec_rule_sections\": [\"specs\", \"checklist\", \"iterations\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先合并 openspec/changes/<change-id>/specs/ 到 openspec/specs/，再归档 change 目录。\", \"归档目录必须落在 openspec/changes/archive/YYYY-MM-DD-<change-id>/，不能改到其它位置。\"], \"blocked_when\": [\"缺少 proposal/specs/design/tasks/checklist/iterations 任一关键产物时，不得执行归档。\"]}}}', '2026-04-20 06:02:13.057', '2026-04-20 06:02:13.057');
