INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg0z004vbq98i8lktbwb', 'cmo6scwtp0000u1984s0is07h', 'role', 'api-governance-specialist', 'API 规范专家', NULL, 'planned', 1, '.agents/roles/domains/governance/api-governance-specialist.md', '{\"name\": \"API 规范专家\", \"source\": \".agents/roles/domains/governance/api-governance-specialist.md\", \"status\": \"planned\", \"domains\": [\"governance\"], \"registry\": \"agents\", \"rawEventId\": \"cmo6sfg0v004ubq98pbmd4bul\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.091', '2026-04-20 06:02:13.091');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg19004xbq9828qnkdmk', 'cmo6scwtp0000u1984s0is07h', 'role', 'route-governance-specialist', '路由规范专家', NULL, 'planned', 1, '.agents/roles/domains/governance/route-governance-specialist.md', '{\"name\": \"路由规范专家\", \"source\": \".agents/roles/domains/governance/route-governance-specialist.md\", \"status\": \"planned\", \"domains\": [\"governance\"], \"registry\": \"agents\", \"rawEventId\": \"cmo6sfg11004wbq98r0qyjsln\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.101', '2026-04-20 06:02:13.101');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg1e004zbq98gnpd0eto', 'cmo6scwtp0000u1984s0is07h', 'role', 'build-specialist', '构建专家', NULL, 'active', 1, '.agents/roles/domains/engineering/build-specialist.md', '{\"name\": \"构建专家\", \"source\": \".agents/roles/domains/engineering/build-specialist.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"registry\": \"agents\", \"rule_ids\": [\"coding-standard\", \"format-check-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg1b004ybq98hg5u7o9r\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"config-and-secret-scan\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"config-and-secret-scan\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先判断问题位于构建入口、构建性能还是产物异常，再给出建议。\", \"优先复用现有构建脚本和配置，不新增无必要工具链。\"], \"blocked_when\": [\"若构建变更会影响发布链但未给出验证与回滚路径，不得直接放行。\"]}}}', '2026-04-20 06:02:13.106', '2026-04-20 06:02:13.106');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg1r0055bq987glr0jk5', 'cmo6scwtp0000u1984s0is07h', 'role', 'dependency-governor', '依赖治理专家', NULL, 'active', 1, '.agents/roles/domains/engineering/dependency-governor.md', '{\"name\": \"依赖治理专家\", \"source\": \".agents/roles/domains/engineering/dependency-governor.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"registry\": \"agents\", \"rule_ids\": [\"coding-standard\", \"format-check-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg1o0054bq98trwjdw3t\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"dependency-impact-graph\", \"config-and-secret-scan\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"dependency-impact-graph\", \"config-and-secret-scan\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先区分新增、升级、移除三类依赖变更，再给最小影响建议。\", \"涉及安装来源、registry 或脚本依赖时，需要补验证与回滚说明。\"], \"blocked_when\": [\"若依赖变更影响面未分析清楚，不得直接建议进入实现或发布。\"]}}}', '2026-04-20 06:02:13.119', '2026-04-20 06:02:13.119');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg24005cbq98gfg3aml2', 'cmo6scwtp0000u1984s0is07h', 'role', 'architecture-advisor', '架构顾问专家', NULL, 'active', 1, '.agents/roles/domains/engineering/architecture-advisor.md', '{\"name\": \"架构顾问专家\", \"source\": \".agents/roles/domains/engineering/architecture-advisor.md\", \"status\": \"active\", \"domains\": [\"engineering\"], \"registry\": \"agents\", \"rule_ids\": [\"project-overview\", \"project-structure\", \"api-standard\", \"route-standard\", \"style-standard\"], \"rawEventId\": \"cmo6sfg21005bbq987tlbc0hv\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"create-proposal\", \"dependency-impact-graph\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"create-proposal\", \"dependency-impact-graph\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先收口模块边界和职责拆分，再讨论实现细节。\", \"若结构性改动会影响多个模块，需要显式列出影响面和拆分建议。\"], \"blocked_when\": [\"若关键边界仍不清楚，不得把结构性问题直接下放到实现阶段临时决定。\"]}}}', '2026-04-20 06:02:13.132', '2026-04-20 06:02:13.132');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg2l005lbq98ltl9nlpu', 'cmo6scwtp0000u1984s0is07h', 'role', 'unit-test-specialist', '单元测试专家', NULL, 'active', 1, '.agents/roles/domains/testing/unit-test-specialist.md', '{\"name\": \"单元测试专家\", \"source\": \".agents/roles/domains/testing/unit-test-specialist.md\", \"status\": \"active\", \"domains\": [\"testing\"], \"registry\": \"agents\", \"rule_ids\": [\"coding-standard\", \"test-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg2i005kbq98tiudk95t\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"create-test\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"create-test\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先判断当前改动是否真的需要补测，再给出最小但有效的测试策略。\", \"quick-fix 下优先读取 bugfix 与实现说明，不把轻量修复默认升级成完整测试改造。\"], \"blocked_when\": [\"若关键回归路径已经受损但仍拒绝补测或给出测试建议，不得给出“风险可忽略”的判断。\"]}}}', '2026-04-20 06:02:13.149', '2026-04-20 06:02:13.149');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg2w005rbq98n287pfw0', 'cmo6scwtp0000u1984s0is07h', 'role', 'e2e-test-specialist', 'E2E 测试专家', NULL, 'active', 1, '.agents/roles/domains/testing/e2e-test-specialist.md', '{\"name\": \"E2E 测试专家\", \"source\": \".agents/roles/domains/testing/e2e-test-specialist.md\", \"status\": \"active\", \"domains\": [\"testing\"], \"registry\": \"agents\", \"rule_ids\": [\"test-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg2t005qbq98hidvgw3w\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"ui-verification\", \"web-design-guidelines\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"ui-verification\", \"web-design-guidelines\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"优先围绕关键发布路径设计验证，不穷举所有页面动作。\", \"验证步骤应能直接服务发布前回归，而不是只做理想化脚本清单。\"], \"blocked_when\": [\"若关键主路径没有任何端到端验证证据，不得给出低风险判断。\"]}}}', '2026-04-20 06:02:13.160', '2026-04-20 06:02:13.160');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg36005xbq985vnn8gto', 'cmo6scwtp0000u1984s0is07h', 'role', 'coverage-analyst', '覆盖率分析专家', NULL, 'planned', 1, '.agents/roles/domains/testing/coverage-analyst.md', '{\"name\": \"覆盖率分析专家\", \"source\": \".agents/roles/domains/testing/coverage-analyst.md\", \"status\": \"planned\", \"domains\": [\"testing\"], \"registry\": \"agents\", \"rawEventId\": \"cmo6sfg34005wbq98nr1p99ov\", \"registryPath\": \".agents/registry/roles.json\"}', '2026-04-20 06:02:13.170', '2026-04-20 06:02:13.170');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg3a005zbq98tc97oo6q', 'cmo6scwtp0000u1984s0is07h', 'role', 'verification-reviewer', '验证评审专家', NULL, 'active', 1, '.agents/roles/domains/testing/verification-reviewer.md', '{\"name\": \"验证评审专家\", \"source\": \".agents/roles/domains/testing/verification-reviewer.md\", \"status\": \"active\", \"domains\": [\"testing\"], \"registry\": \"agents\", \"rule_ids\": [\"style-standard\", \"test-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg37005ybq98enc4edwj\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"ui-verification\", \"web-design-guidelines\"], \"required_inputs\": [\"proposal\", \"specs\", \"design\", \"tasks\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"ui-verification\", \"web-design-guidelines\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"验证评审只补强验收证据与验证口径，不重新定义需求边界。\", \"quick-fix 下优先读取 .ai-spec/history/<run-id>/bugfix.md、implementation-notes.md 与 checklist.md（若已存在）。\"], \"blocked_when\": [\"若关键验收链路没有证据支撑，却仍想给出放行结论，必须维持阻断。\"]}}}', '2026-04-20 06:02:13.174', '2026-04-20 06:02:13.174');
INSERT INTO `RegistryItem` (`id`, `workspaceId`, `category`, `slug`, `name`, `label`, `status`, `version`, `sourcePath`, `payload`, `createdAt`, `updatedAt`) VALUES ('cmo6sfg3k0066bq98cde4cg55', 'cmo6scwtp0000u1984s0is07h', 'role', 'pipeline-specialist', '流水线专家', NULL, 'active', 1, '.agents/roles/domains/delivery/pipeline-specialist.md', '{\"name\": \"流水线专家\", \"source\": \".agents/roles/domains/delivery/pipeline-specialist.md\", \"status\": \"active\", \"domains\": [\"delivery\"], \"registry\": \"agents\", \"rule_ids\": [\"coding-standard\", \"format-check-standard\", \"audit-report-standard\"], \"rawEventId\": \"cmo6sfg3h0065bq989e1q0oio\", \"registryPath\": \".agents/registry/roles.json\", \"skill_priority\": [\"config-and-secret-scan\"], \"required_outputs\": [], \"micro_skill_allowlist\": [\"config-and-secret-scan\"], \"rule_contract_profiles\": {\"default\": {\"must_follow\": [\"先梳理当前流水线里已有的构建、校验和发布步骤，再给治理建议。\", \"要把失败重试、人工确认和回滚关注点写清楚，不只写 happy path。\"], \"blocked_when\": [\"若流水线改动会影响发布稳定性但没有回退思路，不得直接放行。\"]}}}', '2026-04-20 06:02:13.184', '2026-04-20 06:02:13.184');
